entries[18650] = { ["name"] = "Schematic: EZ-Thro Dynamite II", ["text"] = "Requires Engineering (200)\nUse: Teaches you how to make EZ-Thro Dynamite II.\nSell Price: 12 50\nEz-Thro Dynamite II\nRequires Level 30\nUse: Inflicts 213 to 287 Fire damage in a 5 yard radius (Assuming that it gets to the target, some restrictions may apply.) (1 Min Cooldown)\n\"The dynamite for Non-Engineers that rarely* blows up in your hand with over twice the blasting power of standard EZ-Thro.\"\nSell Price: 2\nRequires Solid Blasting Powder , Mageweave Cloth (2)" }
entries[18651] = { ["name"] = "Schematic: Truesilver Transformer", ["text"] = "Requires Engineering (260)\nUse: Teaches you how to make a Truesilver Transformer.\nSell Price: 30\nTruesilver Transformer\nSell Price: 30\nRequires Truesilver Bar (2), Elemental Earth (2), Elemental Air" }
entries[18652] = { ["name"] = "Schematic: Gyrofreeze Ice Reflector", ["text"] = "Requires Engineering (260)\nUse: Teaches you how to make a Gyrofreeze Ice Reflector.\nSell Price: 30\nGyrofreeze Ice Reflector\nBinds when equipped\nTrinket\n+15 Frost Resistance\nRequires Level 47\nRequires Engineering (260)\nUse: Reflects Frost spells back at their caster for 5 sec. Chance to be resisted when used by players over level 60. (5 Min Cooldown)\nSell Price: 1 25\nRequires Thorium Widget (6), Truesilver Transformer (2), Blue Sapphire (2), Essence of Fire (4), Frost Oil (2), Icecap (4)" }
entries[18653] = { ["name"] = "Schematic: Goblin Jumper Cables XL", ["text"] = "Requires Engineering (265)\nRequires Goblin Engineer\nUse: Teaches you how to make a Goblin Jumper Cable XL.\nSell Price: 40\nGoblin Jumper Cables XL\nRequires Engineering (265)\nUse: Jumper Cables will sometimes be able to shock a dead player back to life. Cannot be used when in combat. (30 Min Cooldown)\nSell Price: 20\nRequires Thorium Widget (2), Truesilver Transformer (2), Fused Wiring (2), Ironweb Spider Silk (2), Star Ruby (2)" }
entries[18654] = { ["name"] = "Schematic: Gnomish Alarm-o-Bot", ["text"] = "Requires Engineering (265)\nRequires Gnomish Engineer\nUse: Teaches you how to make an Alarm-o-Bot.\nSell Price: 40\nGnomish Alarm-o-Bot\nRequires Engineering (265)\nUse: Summons a Gnomish Alarm-o-Bot to scan the area for stealthed enemies. The Alarm-o-Bot may occasionally give false signals. Lasts up to 2 min. (5 Min Cooldown)\nSell Price: 30\nRequires Thorium Bar (4), Fused Wiring" }
entries[18655] = { ["name"] = "Schematic: Major Recombobulator", ["text"] = "Requires Engineering (275)\nUse: Teaches you how to make a Major Recombobulator.\nSell Price: 40\nMajor Recombobulator\nTrinket\nRequires Engineering (275)\nUse: Restores 375 to 625 health and mana to a friendly target and attempts to dispel any polymorph effects from them. Reduced effectiveness against polymorph effects from casters of level 61 and higher. (5 Min Cooldown)\n10 ChargesSell Price: 6\nRequires Thorium Tube (2), Truesilver Transformer , Runecloth (2)" }
entries[18656] = { ["name"] = "Schematic: Powerful Seaforium Charge", ["text"] = "Requires Engineering (275)\nUse: Teaches you how to make a Powerful Seaforium Charge.\nSell Price: 40\nPowerful Seaforium Charge\nRequires Engineering (275)\nUse: Blasts open strong locked doors or chests.\nSell Price: 30\nRequires Thorium Widget (2), Dense Blasting Powder (3), Rugged Leather (2), Refreshing Spring Water" }
entries[18657] = { ["name"] = "Schematic: Hyper-Radiant Flame Reflector", ["text"] = "Requires Engineering (290)\nUse: Teaches you how to make a Hyper-Radiant Flame Reflector.\nSell Price: 50\nHyper-Radiant Flame Reflector\nBinds when equipped\nTrinket\n+18 Fire Resistance\nRequires Level 53\nRequires Engineering (290)\nUse: Reflects Fire spells back at their caster for 5 sec. Chance to be resisted when used by players over level 60. (5 Min Cooldown)\nSell Price: 1 25\nRequires Dark Iron Bar (4), Truesilver Transformer (3), Essence of Water (6), Star Ruby (4), Azerothian Diamond (2)" }
entries[18658] = { ["name"] = "Schematic: Ultra-Flash Shadow Reflector", ["text"] = "Requires Engineering (300)\nUse: Teaches you how to make an Ultra-Flash Shadow Reflector.\nSell Price: 60\nUltra-Flash Shadow Reflector\nBinds when equipped\nTrinket\n+20 Shadow Resistance\nRequires Level 55\nRequires Engineering (300)\nUse: Reflects Shadow spells back at their caster for 5 sec. Chance to be resisted when used by players over level 60. (5 Min Cooldown)\nSell Price: 1 25\nRequires Dark Iron Bar (8), Truesilver Transformer (4), Living Essence (6), Essence of Undeath (4), Azerothian Diamond (2), Large Opal (2)" }
